'use strict';

/**
* Factory for creating complex number typed array constructors.
*
* @module @stdlib/array/complex-factory
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
* var realf = require( '@stdlib/complex/float32/real' );
* var imagf = require( '@stdlib/complex/float32/imag' );
* var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
* var factory = require( '@stdlib/array/complex-factory' );
*
* var Complex64Array = factory( 'complex64', Float32Array, Complex64, realf, imagf, reinterpret );
*
* var arr = new Complex64Array( 2 );
* // returns <Complex64Array>
*
* var len = arr.length;
* // returns 2
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var real = require( '@stdlib/complex/float64/real' );
* var imag = require( '@stdlib/complex/float64/imag' );
* var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );
* var factory = require( '@stdlib/array/complex-factory' );
*
* var Complex128Array = factory( 'complex128', Float64Array, Complex128, real, imag, reinterpret );
*
* var arr = new Complex128Array( 2 );
* // returns <Complex128Array>
*
* var len = arr.length;
* // returns 2
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
